CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','volunteer')),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS leads (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL,course TEXT NOT NULL,source TEXT,interest TEXT NOT NULL DEFAULT 'Warm' CHECK(interest IN ('Hot','Warm','Cold')),status TEXT NOT NULL DEFAULT 'Interested' CHECK(status IN ('Interested','Thinking','Not reached','Registered','Not interested')),batch TEXT,volunteer_id BIGINT REFERENCES users(id) ON DELETE SET NULL,last_contacted DATE,next_followup DATE,notes TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS followups (id BIGSERIAL PRIMARY KEY,lead_id BIGINT NOT NULL REFERENCES leads(id) ON DELETE CASCADE,volunteer_id BIGINT REFERENCES users(id) ON DELETE SET NULL,channel TEXT NOT NULL CHECK(channel IN ('WhatsApp','Call','Other')),outcome TEXT,note TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS message_templates (id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,body TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS outbound_messages (id BIGSERIAL PRIMARY KEY,lead_id BIGINT NOT NULL REFERENCES leads(id) ON DELETE CASCADE,volunteer_id BIGINT REFERENCES users(id) ON DELETE SET NULL,template_id BIGINT REFERENCES message_templates(id) ON DELETE SET NULL,channel TEXT NOT NULL DEFAULT 'WhatsApp',body TEXT NOT NULL,provider_message_id TEXT,status TEXT NOT NULL DEFAULT 'queued',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS leads_volunteer_idx ON leads(volunteer_id); CREATE INDEX IF NOT EXISTS leads_followup_idx ON leads(next_followup); CREATE INDEX IF NOT EXISTS leads_status_idx ON leads(status);
